package com.foodwaste.servlet;
import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import java.time.*;
public class DeliveryServlet extends HttpServlet{
 static final String DB="jdbc:sqlite:foodloop.db"; Connection db()throws SQLException{return DriverManager.getConnection(DB);} 
 static String esc(String s){return s==null?"":s.replace("\\","\\\\").replace("\"","\\\"").replace("\r","").replace("\n","\\n");}
 static void json(HttpServletResponse r,String s,int c)throws IOException{r.setStatus(c);r.setContentType("application/json;charset=UTF-8");r.getWriter().print(s);}static int uid(HttpServletRequest q){HttpSession s=q.getSession(false);return s==null||s.getAttribute("userId")==null?-1:(Integer)s.getAttribute("userId");}static String role(HttpServletRequest q){HttpSession s=q.getSession(false);return s==null?"":String.valueOf(s.getAttribute("role"));}
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{try(Connection c=db()){String mode=q.getParameter("mode");if("mine".equals(mode))mine(c,r,uid(q),role(q));else if("all".equals(mode)&&role(q).equals("ADMIN"))all(c,r);else json(r,"[]",200);}catch(Exception e){e.printStackTrace();json(r,"{\"ok\":false,\"message\":\""+esc(e.getMessage())+"\"}",500);}}
 void mine(Connection c,HttpServletResponse r,int id,String role)throws Exception{String sql="select d.*,f.food_name,f.quantity,du.name donor_name,ru.name recipient_name,v.name volunteer_name from deliveries d join food f on d.food_id=f.id left join users v on d.volunteer_id=v.id left join users du on f.donor_id=du.id join claims cl on d.claim_id=cl.id join users ru on cl.recipient_id=ru.id where "+(role.equals("VOLUNTEER")?"d.volunteer_id=?":role.equals("DONOR")?"f.donor_id=?":"cl.recipient_id=?")+" order by d.id desc";try(PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,id);json(r,rows(p.executeQuery()),200);}}
 void all(Connection c,HttpServletResponse r)throws Exception{try(Statement s=c.createStatement();ResultSet x=s.executeQuery("select d.*,f.food_name,du.name donor_name,ru.name recipient_name,v.name volunteer_name from deliveries d join food f on d.food_id=f.id left join users v on d.volunteer_id=v.id join claims cl on d.claim_id=cl.id join users du on f.donor_id=du.id join users ru on cl.recipient_id=ru.id order by d.id desc")){json(r,rows(x),200);}}
 String rows(ResultSet x)throws Exception{StringBuilder b=new StringBuilder("[");boolean f=true;while(x.next()){if(!f)b.append(',');f=false;b.append("{\"id\":").append(x.getInt("id")).append(",\"foodName\":\"").append(esc(x.getString("food_name"))).append("\",\"quantity\":\"").append(esc(x.getString("quantity"))).append("\",\"donorName\":\"").append(esc(x.getString("donor_name"))).append("\",\"recipientName\":\"").append(esc(x.getString("recipient_name"))).append("\",\"volunteerName\":\"").append(esc(x.getString("volunteer_name"))).append("\",\"pickupLocation\":\"").append(esc(x.getString("pickup_location"))).append("\",\"dropLocation\":\"").append(esc(x.getString("drop_location"))).append("\",\"distanceKm\":").append(x.getDouble("distance_km")).append(",\"ratePerKm\":").append(x.getDouble("rate_per_km")).append(",\"volunteerFee\":").append(x.getDouble("volunteer_fee")).append(",\"status\":\"").append(esc(x.getString("status"))).append("\",\"paymentStatus\":\"").append(esc(x.getString("payment_status"))).append("\"}");}return b.append(']').toString();}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{String a=q.getParameter("action");try(Connection c=db()){switch(a==null?"":a){case"assign":assign(q,r,c);break;case"status":status(q,r,c);break;case"add-volunteer":addVolunteer(q,r,c);break;case"volunteer-availability":availability(q,r,c);break;default:json(r,"{\"ok\":false,\"message\":\"Unknown delivery action\"}",404);}}catch(Exception e){e.printStackTrace();json(r,"{\"ok\":false,\"message\":\""+esc(e.getMessage())+"\"}",500);}}
 void assign(HttpServletRequest q,HttpServletResponse r,Connection c)throws Exception{int donor=uid(q);if(!role(q).equals("DONOR")){json(r,"{\"ok\":false,\"message\":\"Donor login required.\"}",401);return;}int claim=Integer.parseInt(q.getParameter("claimId")),vol=Integer.parseInt(q.getParameter("volunteerId"));double km=Double.parseDouble(q.getParameter("distanceKm")),rate=Double.parseDouble(q.getParameter("ratePerKm"));if(km<=0||rate<0){json(r,"{\"ok\":false,\"message\":\"Enter valid distance and rate.\"}",400);return;}double fee=Math.round(km*rate*100.0)/100.0;String pick,drop,food;try(PreparedStatement p=c.prepareStatement("select f.location,u.location,f.id from claims cl join food f on cl.food_id=f.id join users u on cl.recipient_id=u.id where cl.id=? and f.donor_id=? and cl.status='APPROVED'")){p.setInt(1,claim);p.setInt(2,donor);ResultSet x=p.executeQuery();if(!x.next()){json(r,"{\"ok\":false,\"message\":\"Accepted claim not found.\"}",404);return;}pick=x.getString(1);drop=x.getString(2);food=x.getString(3);}try(PreparedStatement p=c.prepareStatement("select availability from users where id=? and role='VOLUNTEER'")){p.setInt(1,vol);ResultSet x=p.executeQuery();if(!x.next()||!"AVAILABLE".equalsIgnoreCase(x.getString(1))){json(r,"{\"ok\":false,\"message\":\"Volunteer is not available.\"}",409);return;}}try(PreparedStatement p=c.prepareStatement("insert into deliveries(food_id,claim_id,volunteer_id,pickup_location,drop_location,distance_km,rate_per_km,volunteer_fee,status,payment_status,assigned_at) values(?,?,?,?,?,?,?,?,?,?,?)")){p.setInt(1,Integer.parseInt(food));p.setInt(2,claim);p.setInt(3,vol);p.setString(4,pick);p.setString(5,drop);p.setDouble(6,km);p.setDouble(7,rate);p.setDouble(8,fee);p.setString(9,"ASSIGNED");p.setString(10,"PENDING");p.setString(11,LocalDateTime.now().toString());p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("update users set availability='BUSY' where id=?")){p.setInt(1,vol);p.executeUpdate();}json(r,"{\"ok\":true,\"message\":\"Volunteer assigned. Payout ₹"+String.format(java.util.Locale.US,"%.2f",fee)+"\"}",200);}
 void status(HttpServletRequest q,HttpServletResponse r,Connection c)throws Exception{int id=Integer.parseInt(q.getParameter("deliveryId"));String st=q.getParameter("status");if(!st.matches("ACCEPTED|PICKED_UP|ON_THE_WAY|DELIVERED")){json(r,"{\"ok\":false,\"message\":\"Invalid status.\"}",400);return;}int user=uid(q);String where=role(q).equals("VOLUNTEER")?" and volunteer_id="+user:"";try(PreparedStatement p=c.prepareStatement("update deliveries set status=?,picked_up_at=case when ?='PICKED_UP' then ? else picked_up_at end,delivered_at=case when ?='DELIVERED' then ? else delivered_at end where id=?"+where)){p.setString(1,st);p.setString(2,st);p.setString(3,LocalDateTime.now().toString());p.setString(4,st);p.setString(5,LocalDateTime.now().toString());p.setInt(6,id);int n=p.executeUpdate();if(n==0){json(r,"{\"ok\":false,\"message\":\"Delivery not found or not assigned to you.\"}",404);return;}}if("DELIVERED".equals(st)){try(PreparedStatement p=c.prepareStatement("update deliveries set payment_status='PAID' where id=?")){p.setInt(1,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("update users set availability='AVAILABLE' where id=(select volunteer_id from deliveries where id=?)")){p.setInt(1,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("update claims set status='COMPLETED' where id=(select claim_id from deliveries where id=?)")){p.setInt(1,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("update food set status='COMPLETED' where id=(select food_id from deliveries where id=?)")){p.setInt(1,id);p.executeUpdate();}}json(r,"{\"ok\":true,\"message\":\"Delivery status updated.\"}",200);}
 void addVolunteer(HttpServletRequest q,HttpServletResponse r,Connection c)throws Exception{if(!role(q).equals("ADMIN")){json(r,"{\"ok\":false,\"message\":\"Admin login required.\"}",401);return;}String n=q.getParameter("name"),email=q.getParameter("email"),phone=q.getParameter("phone"),loc=q.getParameter("location"),vehicle=q.getParameter("vehicle");if(n==null||email==null||q.getParameter("password")==null){json(r,"{\"ok\":false,\"message\":\"Name, email and password are required.\"}",400);return;}try(PreparedStatement p=c.prepareStatement("insert into users(name,email,password,role,phone,location,availability,vehicle,created_at) values(?,?,?,?,?,?,?,?,?)")){p.setString(1,n);p.setString(2,email);p.setString(3,org.mindrot.jbcrypt.BCrypt.hashpw(q.getParameter("password"),org.mindrot.jbcrypt.BCrypt.gensalt(10)));p.setString(4,"VOLUNTEER");p.setString(5,phone);p.setString(6,loc);p.setString(7,"AVAILABLE");p.setString(8,vehicle);p.setString(9,LocalDateTime.now().toString());p.executeUpdate();}json(r,"{\"ok\":true,\"message\":\"Volunteer added.\"}",200);}
 void availability(HttpServletRequest q,HttpServletResponse r,Connection c)throws Exception{if(!role(q).equals("VOLUNTEER")){json(r,"{\"ok\":false}",401);return;}String a=q.getParameter("availability");if(!a.matches("AVAILABLE|OFFLINE")){json(r,"{\"ok\":false,\"message\":\"Invalid availability.\"}",400);return;}try(PreparedStatement p=c.prepareStatement("update users set availability=? where id=?")){p.setString(1,a);p.setInt(2,uid(q));p.executeUpdate();}json(r,"{\"ok\":true}",200);}
}
